<div class="section-heading"><div><div class="eyebrow">Recorrência</div><h1>Pacotes e mensalidades</h1><p class="text-secondary mb-0">Venda sessões antecipadas ou crie um clube recorrente com cobrança manual ou automática pelo provedor da empresa.</p></div></div><?php if(isset($_GET['automatic_created'])):?><div class="alert alert-success mt-3">Mensalidade criada. Envie o link de autorização do Mercado Pago ao cliente.</div><?php endif;?>
<div class="row g-4"><div class="col-lg-6"><div class="card"><div class="card-body"><h2 class="h5">Novo pacote</h2><form method="post" action="/packages" class="row g-2"><?=\App\Core\CSRF::field()?><div class="col-md-6"><input class="form-control" name="name" placeholder="Ex.: Clube 4 cortes" required></div><div class="col-md-3"><input class="form-control" name="price" type="number" step=".01" min="0" placeholder="Preço" required></div><div class="col-md-3"><input class="form-control" name="validity_days" type="number" min="1" placeholder="Validade dias"></div><div class="col-md-8"><select class="form-select" name="service_id" required><option value="">Serviço</option><?php foreach($services as $s):?><option value="<?=(int)$s['id']?>"><?=htmlspecialchars($s['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" name="quantity" type="number" min="1" value="4"></div><div class="col-md-2"><button class="btn btn-primary w-100">Criar</button></div></form></div></div></div>
<div class="col-lg-6"><div class="card"><div class="card-body"><h2 class="h5">Vender pacote / clube</h2><form method="post" action="/packages/sell" class="row g-2"><?=\App\Core\CSRF::field()?><div class="col-md-5"><select class="form-select" name="customer_id" required><option value="">Cliente</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>"><?=htmlspecialchars($c['name'])?><?=!empty($c['email'])?' · '.htmlspecialchars($c['email']):''?></option><?php endforeach;?></select></div><div class="col-md-5"><select class="form-select" name="package_id" required><option value="">Pacote</option><?php foreach($packages as $p):?><option value="<?=(int)$p['id']?>"><?=htmlspecialchars($p['name'])?> · R$ <?=number_format((float)$p['price'],2,',','.')?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Vender</button></div><?php if($financeEnabled):?><div class="col-md-6"><label class="form-check mt-2"><input class="form-check-input" type="checkbox" name="recurring" value="1"> Transformar em mensalidade recorrente</label></div><div class="col-md-6"><select class="form-select" name="cycle"><option value="monthly">Mensal</option><option value="quarterly">Trimestral</option></select></div><div class="col-12"><label class="form-check"><input class="form-check-input" type="checkbox" name="automatic_billing" value="1" <?=$automaticBillingAvailable?'':'disabled'?>> Cobrança automática pelo Mercado Pago da empresa</label><small class="text-secondary"><?=$automaticBillingAvailable?'O cliente receberá um link para autorizar a cobrança recorrente. Créditos só são liberados após pagamento confirmado.':'Conecte o Mercado Pago em Bancos e Pagamentos para habilitar.'?></small></div><?php else:?><div class="col-12"><small class="text-secondary">Mensalidades recorrentes ficam disponíveis quando o plano inclui Financeiro.</small></div><?php endif;?></form></div></div></div></div>
<div class="row g-4 mt-1"><div class="col-lg-6"><div class="card"><div class="card-header"><strong>Catálogo</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Pacote</th><th>Inclui</th><th>Preço</th></tr></thead><tbody><?php foreach($packages as $p):?><tr><td><?=htmlspecialchars($p['name'])?></td><td><?=htmlspecialchars($p['items']??'-')?></td><td>R$ <?=number_format((float)$p['price'],2,',','.')?></td></tr><?php endforeach;?></tbody></table></div></div></div><div class="col-lg-6"><div class="card"><div class="card-header"><strong>Créditos liberados</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Cliente</th><th>Pacote</th><th>Status</th><th>Validade</th></tr></thead><tbody><?php foreach($customerPackages as $p):?><tr><td><?=htmlspecialchars($p['customer_name'])?></td><td><?=htmlspecialchars($p['package_name'])?></td><td><?=htmlspecialchars(['active'=>'Ativo','used'=>'Utilizado','expired'=>'Expirado','cancelled'=>'Cancelado'][$p['status']]??$p['status'])?></td><td><?=$p['expires_at']?date('d/m/Y',strtotime($p['expires_at'])):'Sem validade'?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<div class="card mt-4"><div class="card-header"><strong>Mensalidades / Clube</strong></div><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Cliente</th><th>Pacote</th><th>Ciclo</th><th>Valor</th><th>Cobrança</th><th>Próxima</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($memberships as $m):?><tr><td><strong><?=htmlspecialchars($m['customer_name'])?></strong><small class="d-block text-secondary"><?=htmlspecialchars($m['customer_email']??'')?></small></td><td><?=htmlspecialchars($m['package_name'])?></td><td><?=$m['cycle']==='quarterly'?'Trimestral':'Mensal'?></td><td>R$ <?=number_format((float)$m['recurring_amount'],2,',','.')?></td><td><?php if(($m['billing_mode']??'manual')==='provider'):?><span class="badge text-bg-info">Automática</span><small class="d-block text-secondary"><?=htmlspecialchars($m['recurring_status']??$m['provider_status']??'pending')?></small><?php if(!empty($m['recurring_checkout_url'])):?><a class="btn btn-sm btn-outline-primary mt-1" target="_blank" rel="noopener" href="<?=htmlspecialchars($m['recurring_checkout_url'])?>">Abrir autorização</a><?php endif;?><?php else:?><span class="badge text-bg-light">Manual</span><?php endif;?></td><td><?=date('d/m/Y',strtotime($m['next_due_at']))?></td><td><span class="badge text-bg-<?=$m['status']==='active'?'success':'secondary'?>"><?=htmlspecialchars(['active'=>'Ativa','paused'=>'Pausada','cancelled'=>'Cancelada'][$m['status']]??$m['status'])?></span></td><td><div class="d-flex gap-1 flex-wrap"><?php if($m['status']==='active'&&($m['billing_mode']??'manual')!=='provider'&&$automaticBillingAvailable):?><form method="post" action="/memberships/<?=(int)$m['id']?>/automatic"><?=\App\Core\CSRF::field()?><button class="btn btn-sm btn-outline-primary">Ativar automática</button></form><?php endif;?><?php if($m['status']==='active'):?><form method="post" action="/memberships/<?=(int)$m['id']?>/cancel" onsubmit="return confirm('Cancelar esta mensalidade?')"><?=\App\Core\CSRF::field()?><button class="btn btn-sm btn-outline-danger">Cancelar</button></form><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$memberships):?><tr><td colspan="8" class="text-center text-secondary py-4">Nenhuma mensalidade recorrente cadastrada.</td></tr><?php endif;?></tbody></table></div></div>
